from taf.fdsw.rc.interfaces.FDSW24C.fdsw import FDSW24C
from taf.fdsw.rc.interfaces.FDSW25A.diagnostics.diagnostic import Diagnostic25A


class FDSW25A(FDSW24C):
    VERSION_NAME = "FDSW25A"
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super().__init__(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
            secure=secure,
        )
        self.diagnostics = Diagnostic25A(self._client)
